/* Modern Minimal Theme - Auto-generated from tweakcn */

/* Light mode */
[data-theme="modern-minimal-light"] {
  --background: rgb(255, 255, 255);
  --foreground: rgb(51, 51, 51);
  --card: rgb(255, 255, 255);
  --card-foreground: rgb(51, 51, 51);
  --popover: rgb(255, 255, 255);
  --popover-foreground: rgb(51, 51, 51);
  --primary: rgb(57, 129, 246);
  --primary-foreground: rgb(255, 255, 255);
  --secondary: rgb(245, 245, 245);
  --secondary-foreground: rgb(75, 86, 102);
  --muted: rgb(248, 248, 248);
  --muted-foreground: rgb(108, 114, 126);
  --accent: rgb(222, 242, 255);
  --accent-foreground: rgb(30, 58, 139);
  --destructive: rgb(241, 68, 68);
  --destructive-foreground: rgb(255, 255, 255);
  --border: rgb(228, 232, 239);
  --input: rgb(228, 232, 239);
  --ring: rgb(57, 129, 246);
  --chart-1: rgb(57, 129, 246);
  --chart-2: rgb(36, 99, 239);
  --chart-3: rgb(29, 78, 218);
  --chart-4: rgb(29, 63, 173);
  --chart-5: rgb(30, 58, 139);
  --radius: 0.375rem;
  --sidebar: rgb(248, 248, 248);
  --sidebar-foreground: rgb(51, 51, 51);
  --sidebar-primary: rgb(57, 129, 246);
  --sidebar-primary-foreground: rgb(255, 255, 255);
  --sidebar-accent: rgb(222, 242, 255);
  --sidebar-accent-foreground: rgb(30, 58, 139);
  --sidebar-border: rgb(228, 232, 239);
  --sidebar-ring: rgb(57, 129, 246);
  --font-sans: Inter, sans-serif;
  --font-serif: Source Serif 4, serif;
  --font-mono: JetBrains Mono, monospace;
  --shadow-color: rgb(0, 0, 0);
  --shadow-opacity: 0.1;
  --shadow-blur: 3px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0;
  --shadow-offset-y: 1px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
  --shadow-xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
  --shadow-sm:
    0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 1px 2px -1px hsl(0 0% 0% / 0.1);
  --shadow: 0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 1px 2px -1px hsl(0 0% 0% / 0.1);
  --shadow-md:
    0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 2px 4px -1px hsl(0 0% 0% / 0.1);
  --shadow-lg:
    0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 4px 6px -1px hsl(0 0% 0% / 0.1);
  --shadow-xl:
    0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 8px 10px -1px hsl(0 0% 0% / 0.1);
  --shadow-2xl: 0 1px 3px 0px hsl(0 0% 0% / 0.25);
  --tracking-normal: 0em;
}

/* Dark mode */
