  --popover-foreground: rgb(228, 228, 228);
  --primary: rgb(57, 129, 246);
  --primary-foreground: rgb(255, 255, 255);
  --secondary: rgb(38, 38, 38);
  --secondary-foreground: rgb(228, 228, 228);
  --muted: rgb(38, 38, 38);
  --muted-foreground: rgb(164, 164, 164);
  --accent: rgb(30, 58, 139);
  --accent-foreground: rgb(189, 218, 255);
  --destructive: rgb(241, 68, 68);
  --destructive-foreground: rgb(255, 255, 255);
  --border: rgb(64, 64, 64);
  --input: rgb(64, 64, 64);
  --ring: rgb(57, 129, 246);
  --chart-1: rgb(97, 164, 247);
  --chart-2: rgb(57, 129, 246);
  --chart-3: rgb(36, 99, 239);
  --chart-4: rgb(29, 78, 218);
  --chart-5: rgb(29, 63, 173);
  --radius: 0.375rem;
  --sidebar: rgb(22, 22, 22);
  --sidebar-foreground: rgb(228, 228, 228);
  --sidebar-primary: rgb(57, 129, 246);
  --sidebar-primary-foreground: rgb(255, 255, 255);
  --sidebar-accent: rgb(30, 58, 139);
